    return None


def extract_properties(schema: Dict[str, Any]) -> Dict[str, Any]:
    if not schema:
        return {}
    if isinstance(schema.get("properties"), dict):
        return schema["properties"]
    if isinstance(schema.get("schema"), dict):
        return extract_properties(schema["schema"])
